   127	/*!
   128	 * \brief   pixProcessBarcodes()
   129	 *
   130	 * \param[in]    pixs        any depth
   131	 * \param[in]    format      L_BF_ANY, L_BF_CODEI2OF5, L_BF_CODE93, ...
   132	 * \param[in]    method      L_USE_WIDTHS, L_USE_WINDOWS
   133	 * \param[out]   psaw        [optional] sarray of bar widths
   134	 * \param[in]    debugflag   use 1 to generate debug output
   135	 * \return  sarray text of barcodes, or NULL if none found or on error
   136	 */
   137	SARRAY *
   138	pixProcessBarcodes(PIX      *pixs,
   139	                   l_int32   format,
   140	                   l_int32   method,
   141	                   SARRAY  **psaw,
   142	                   l_int32   debugflag)
   143	{
   144	PIX     *pixg;
   145	PIXA    *pixa;
   146	SARRAY  *sad;
   147	
   148	    PROCNAME("pixProcessBarcodes");
   149	
   150	    if (psaw) *psaw = NULL;
   151	    if (!pixs)
   152	        return (SARRAY *)ERROR_PTR("pixs not defined", procName, NULL);
   153	    if (format != L_BF_ANY && !barcodeFormatIsSupported(format))
   154	        return (SARRAY *)ERROR_PTR("unsupported format", procName, NULL);
   155	    if (method != L_USE_WIDTHS && method != L_USE_WINDOWS)
   156	        return (SARRAY *)ERROR_PTR("invalid method", procName, NULL);
   157	
   158	        /* Get an 8 bpp image, no cmap */
   159	    if (pixGetDepth(pixs) == 8 && !pixGetColormap(pixs))
   160	        pixg = pixClone(pixs);
   161	    else
   162	        pixg = pixConvertTo8(pixs, 0);
   163	
   164	    if ((pixa = pixExtractBarcodes(pixg, debugflag)) == NULL) {
   165	        pixDestroy(&pixg);
   166	        return (SARRAY *)ERROR_PTR("no barcode(s) found", procName, NULL);
   167	    }
   168	
   169	    sad = pixReadBarcodes(pixa, format, method, psaw, debugflag);
   170	
   171	    pixDestroy(&pixg);
   172	    pixaDestroy(&pixa);
   173	    return sad;
   174	}
