   246	/*!
   247	 * \brief   pixReadBarcodes()
   248	 *
   249	 * \param[in]    pixa        of 8 bpp deskewed and cropped barcodes
   250	 * \param[in]    format      L_BF_ANY, L_BF_CODEI2OF5, L_BF_CODE93, ...
   251	 * \param[in]    method      L_USE_WIDTHS, L_USE_WINDOWS;
   252	 * \param[out]   psaw        [optional] sarray of bar widths
   253	 * \param[in]    debugflag   use 1 to generate debug output
   254	 * \return  sa   sarray of widths, one string for each barcode found,
   255	 *               or NULL on error
   256	 */
   257	SARRAY *
   258	pixReadBarcodes(PIXA     *pixa,
   259	                l_int32   format,
   260	                l_int32   method,
   261	                SARRAY  **psaw,
   262	                l_int32   debugflag)
   263	{
   264	char      *barstr, *data;
   265	char       emptystring[] = "";
   266	l_int32    i, j, n, nbars, ival;
   267	NUMA      *na;
   268	PIX       *pixt;
   269	SARRAY    *saw, *sad;
   270	
   271	    PROCNAME("pixReadBarcodes");
   272	
   273	    if (psaw) *psaw = NULL;
   274	    if (!pixa)
   275	        return (SARRAY *)ERROR_PTR("pixa not defined", procName, NULL);
   276	    if (format != L_BF_ANY && !barcodeFormatIsSupported(format))
   277	        return (SARRAY *)ERROR_PTR("unsupported format", procName, NULL);
   278	    if (method != L_USE_WIDTHS && method != L_USE_WINDOWS)
   279	        return (SARRAY *)ERROR_PTR("invalid method", procName, NULL);
   280	
   281	    n = pixaGetCount(pixa);
   282	    saw = sarrayCreate(n);
   283	    sad = sarrayCreate(n);
   284	    for (i = 0; i < n; i++) {
   285	            /* Extract the widths of the lines in each barcode */
   286	        pixt = pixaGetPix(pixa, i, L_CLONE);
   287	        na = pixReadBarcodeWidths(pixt, method, debugflag);
   288	        pixDestroy(&pixt);
   289	        if (!na) {
   290	            ERROR_INT("valid barcode widths not returned", procName, 1);
   291	            continue;
   292	        }
   293	
   294	            /* Save the widths as a string */
   295	        nbars = numaGetCount(na);
   296	        barstr = (char *)LEPT_CALLOC(nbars + 1, sizeof(char));
   297	        for (j = 0; j < nbars; j++) {
   298	            numaGetIValue(na, j, &ival);
   299	            barstr[j] = 0x30 + ival;
   300	        }
   301	        sarrayAddString(saw, barstr, L_INSERT);
   302	        numaDestroy(&na);
   303	
   304	            /* Decode the width strings */
   305	        data = barcodeDispatchDecoder(barstr, format, debugflag);
   306	        if (!data) {
   307	            ERROR_INT("barcode not decoded", procName, 1);
   308	            sarrayAddString(sad, emptystring, L_COPY);
   309	            continue;
   310	        }
   311	        sarrayAddString(sad, data, L_INSERT);
   312	    }
   313	
   314	        /* If nothing found, clean up */
   315	    if (sarrayGetCount(saw) == 0) {
   316	        sarrayDestroy(&saw);
   317	        sarrayDestroy(&sad);
   318	        return (SARRAY *)ERROR_PTR("no valid barcode data", procName, NULL);
   319	    }
   320	
   321	    if (psaw)
   322	        *psaw = saw;
   323	    else
   324	        sarrayDestroy(&saw);
   325	
   326	    return sad;
   327	}
